def workspace_path(value, *, must_exist):
    p = pathlib.Path(value)
    if not p.is_absolute() or '..' in p.parts or not p.is_relative_to(WORKSPACE):
        raise ValueError('path must be absolute under /workspace without traversal')
    current = pathlib.Path('/')
    for part in p.parts[1:]:
        current /= part
        try: st = current.lstat()
        except FileNotFoundError:
            if must_exist: raise
            break
        if stat.S_ISLNK(st.st_mode): raise ValueError('symlink path component refused')
    return p

def regular_bytes(directory, name):
    if name not in EXPECTED_FILES and name != 'SHA256SUMS': raise ValueError('unexpected source name')
    flags = os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0)
    fd = os.open(directory / name, flags)
    try:
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_size > 20000000: raise ValueError('source is not a bounded regular file')
        with os.fdopen(fd, 'rb', closefd=False) as f: data = f.read(20000001)
        if len(data) != st.st_size: raise ValueError('source size changed during read')
        return data
    finally: os.close(fd)

def load_verified(directory):
    raw = {'SHA256SUMS': regular_bytes(directory, 'SHA256SUMS')}
    text = raw['SHA256SUMS'].decode('utf-8', 'strict')
    records = []
    for line in text.splitlines():
        match = re.fullmatch(r'([0-9a-f]{64})  ([A-Za-z0-9._-]+)', line)
        if not match: raise ValueError('invalid checksum entry')
        digest, name = match.groups()
        if name not in EXPECTED_FILES or name in {x[0] for x in records}: raise ValueError('unexpected or duplicate checksum entry')
        records.append((name, digest))
    if {name for name, _ in records} != EXPECTED_FILES: raise ValueError('checksum set is incomplete')
    for name, digest in records:
        raw[name] = regular_bytes(directory, name)
        if hashlib.sha256(raw[name]).hexdigest() != digest: raise ValueError('source checksum mismatch: ' + name)
    return raw

