def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--source', required=True, help='absolute original snapshot directory under /workspace')
    mode = ap.add_mutually_exclusive_group()
    mode.add_argument('--check', action='store_true', help='compare to retained outputs (default)')
    mode.add_argument('--output-dir', help='create a new directory under /workspace and write the four outputs')
    args = ap.parse_args()
    source = workspace_path(args.source, must_exist=True)
    if not source.is_dir(): raise ValueError('source must be a directory')
    raw = load_verified(source)
    if args.output_dir:
        out = workspace_path(args.output_dir, must_exist=False)
        if out.is_relative_to(source) or source.is_relative_to(out): raise ValueError('output overlaps source')
        if not out.parent.is_dir(): raise ValueError('output parent must already exist')
        out.mkdir(mode=0o700)  # exclusive; never overwrite any prior output
        generate(source, out, raw)
        print('wrote four files to', out)
    else:
        temp_root = workspace_path('/workspace/build/builderbob', must_exist=True)
        with tempfile.TemporaryDirectory(prefix='jefferson-intake-check-', dir=temp_root) as tmp:
            out = pathlib.Path(tmp)
            generate(source, out, raw)
            for name in OUTPUTS:
                expected = SNAPSHOT / name
                if expected.is_symlink() or not expected.is_file() or (out / name).read_bytes() != expected.read_bytes():
                    raise ValueError('retained output mismatch: ' + name)
        print('PASS: four retained outputs match byte-for-byte')

if __name__ == '__main__':
    main()
